#include <iostream>
#include <string>

int main() {
    int n;
    std::string str;
    std::cin >> n;
    std::cin >> str;

    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (i + 2 < n && str[i] == 'x' && str[i+1] == 'x' && str[i+2] == 'x') {
            count++;
        }
    }
    std::cout << count;
    return 0;
}

